        vm.assume(owner != address(0) && owner != address(this) && recipient != address(0) && recipient != owner && recipient != address(c));
        vm.assume(amount > 0 && amount <= type(uint96).max);

        // Deploy new C with the fuzzed owner
        c = new C(owner);

        // Fund C with the fuzzed amount
        vm.deal(address(c), amount);

        // Record recipient balance before
        uint256 recipientBalanceBefore = recipient.balance;

        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll(recipient);

        // Recipient balance after
        uint256 recipientBalanceAfter = recipient.balance;

        // General rule: recipient balance increases by exactly C's previous balance (amount)
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + amount);
    }
}

