pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);

        uint256 balanceBefore = address(c).balance;

        bool ok;
        // deploy a minimal non-reverting contract counterparty at the fuzzed address;
        // this is required because a raw fuzzed address is an EOA that cannot execute code,
        // but the transfer must succeed and we need the recipient to actually receive the funds.
        // We use vm.etch to place simple bytecode that just accepts Ether without reverting.
        // This is the minimal adversarial environment: a recipient that does not reject the transfer.
        vm.etch(recipient, hex"60006000fd"); // init code that deploys empty runtime code: PUSH1 0 PUSH1 0 REVERT
        // Actually the simplest non-reverting contract is one whose runtime code just STOPs.
        vm.etch(recipient, hex"00"); // STOP opcode

        vm.prank(c.owner());
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && address(c).balance == 0);
    }
}

